@include('admin.includes.header')<div class="main-content"><div class="page-content"><div class="container-fluid"><div class="card"><div class="card-body"><h4>Contact requests</h4><form class="row g-2 my-3"><div class="col-md-7"><input class="form-control" name="q" value="{{request('q')}}" placeholder="Search name, phone or message"></div><div class="col-md-3"><select class="form-select" name="read"><option value="">All</option><option value="0" @selected(request('read')==='0')>Unread</option><option value="1" @selected(request('read')==='1')>Read</option></select></div><div class="col-md-2"><button class="btn btn-outline-primary">Filter</button></div></form><table class="table"><thead><tr><th>Name</th><th>Phone</th><th>Message</th><th>Status</th><th>Date</th><th>Actions</th></tr></thead><tbody>@foreach($contacts as $contact)<tr><td>{{$contact->name}}</td><td>{{$contact->phone}}</td><td>{{str($contact->message)->limit(70)}}</td><td>{{$contact->is_read?'Read':'Unread'}}</td><td>{{$contact->created_at->format('Y-m-d H:i')}}</td><td><a class="btn btn-sm btn-primary" href="{{route('contacts.show',$contact)}}">View</a> <form class="d-inline" method="post" action="{{route('contacts.destroy',$contact)}}">@csrf @method('DELETE')<button class="btn btn-sm btn-danger">Delete</button></form></td></tr>@endforeach</tbody></table>{{$contacts->links('admin.vendor.pagination.bootstrap-5')}}</div></div></div></div></div>@include('admin.includes.footer')
